#include "sblr_sec_revoke_runtime.hpp"
#include <cstring>
namespace scratchbird::engine::sblr{namespace{void w16(std::vector<uint8_t>&b,size_t o,uint16_t v){b[o]=v;b[o+1]=v>>8;}void w32(std::vector<uint8_t>&b,size_t o,uint32_t v){for(int i=0;i<4;i++)b[o+i]=v>>(8*i);}void w64(std::vector<uint8_t>&b,size_t o,uint64_t v){for(int i=0;i<8;i++)b[o+i]=v>>(8*i);}uint64_t r64(const uint8_t*p,size_t o){uint64_t v=0;for(int i=0;i<8;i++)v|=uint64_t(p[o+i])<<(8*i);return v;}void cp(std::vector<uint8_t>&b,size_t o,const void*p,size_t n){std::memcpy(b.data()+o,p,n);}bool h(const uint8_t*p,size_t n,const char*m,size_t z,std::string*d){if(!p||n!=z||std::memcmp(p,m,4)||p[4]!=1||(uint16_t(p[6])|uint16_t(p[7])<<8)!=z||(uint32_t(p[8])|uint32_t(p[9])<<8|uint32_t(p[10])<<16|uint32_t(p[11])<<24)!=z){if(d)*d="SRV fixed-size header invalid";return false;}return true;}}
std::vector<uint8_t> EncodeSblrSecRevokeRequestV1(const SblrSecRevokeRequestV1&v){std::vector<uint8_t>b(64);cp(b,0,"SRVQ",4);w16(b,4,1);w16(b,6,64);w32(b,8,64);cp(b,16,v.receipt.data(),16);w64(b,32,v.occurrence);return b;}bool DecodeSblrSecRevokeRequestV1(const uint8_t*p,size_t n,SblrSecRevokeRequestV1*o,std::string*d){if(!o||!h(p,n,"SRVQ",64,d))return false;std::memcpy(o->receipt.data(),p+16,16);o->occurrence=r64(p,32);return o->occurrence!=0;}
std::vector<uint8_t> EncodeSblrSecRevokeDescriptorV1(const SblrSecRevokeDescriptorV1&v,bool op){std::vector<uint8_t>b(128);cp(b,0,op?"SRVO":"SRVD",4);w16(b,4,1);w16(b,6,128);w32(b,8,128);cp(b,16,v.grant_uuid.data(),16);cp(b,32,v.grantee_uuid.data(),16);cp(b,48,v.target_object_uuid.data(),16);w64(b,64,v.expected_generation);w64(b,72,v.catalog_generation);w64(b,80,v.security_generation);w64(b,88,v.availability);cp(b,96,v.descriptor_evidence.data(),16);return b;}bool DecodeSblrSecRevokeDescriptorV1(const uint8_t*p,size_t n,SblrSecRevokeDescriptorV1*o,std::string*d,bool op){if(!o||!h(p,n,op?"SRVO":"SRVD",128,d))return false;std::memcpy(o->grant_uuid.data(),p+16,16);std::memcpy(o->grantee_uuid.data(),p+32,16);std::memcpy(o->target_object_uuid.data(),p+48,16);o->expected_generation=r64(p,64);o->catalog_generation=r64(p,72);o->security_generation=r64(p,80);o->availability=r64(p,88);std::memcpy(o->descriptor_evidence.data(),p+96,16);return o->availability!=0;}
std::vector<uint8_t> EncodeSblrSecRevokeResultV1(const SblrSecRevokeResultV1&v){std::vector<uint8_t>b(128);cp(b,0,"SRVR",4);w16(b,4,1);w16(b,6,128);w32(b,8,128);b[16]=v.status;b[17]=v.publication_barrier;cp(b,24,v.grant_uuid.data(),16);w64(b,40,v.generation);w64(b,48,v.security_generation);w64(b,56,v.availability);cp(b,64,v.effect_evidence.data(),32);return b;}bool DecodeSblrSecRevokeResultV1(const uint8_t*p,size_t n,SblrSecRevokeResultV1*o,std::string*d){if(!o||!h(p,n,"SRVR",128,d))return false;o->status=p[16];o->publication_barrier=p[17];std::memcpy(o->grant_uuid.data(),p+24,16);o->generation=r64(p,40);o->security_generation=r64(p,48);o->availability=r64(p,56);std::memcpy(o->effect_evidence.data(),p+64,32);return true;}}
